from __future__ import annotations

from typing import TypedDict

from pyvkteamsclient.staffd.base.client import BaseStaffDClient


class StaffdUser(TypedDict):
    id: str
    firstName: str
    lastName: str
    groupID: str


class UsersMethods(BaseStaffDClient):
    def create_user(self, users: list[StaffdUser]):
        return self.post(path="users", json={"users": users})

    def get_user_by_id(self, user_id: str | int):
        return self.get(path=f"users/{user_id}")

    def get_users_list(self, _from: int = 0, max_users: int = 1000, include_attributes: bool = True):
        return self.get(
            path="users/list",
            **{
                "from": _from,
                "max": max_users,
                "includeAttributes": int(include_attributes),
            },
        )

    def remove_user(self, user_id: str | int):
        return self.delete(path=f"users/{user_id}")
